# Lote 09: posições 70 a 77 do A1 (We're/They're, and/but/or, perguntas com to be, Where is/are, Yes I am / No I'm not).
# TROCAS DE OBRA: pos 71: de How Doth the Little Busy Bee (repetida da pos 70) para The Three Little Pigs
# TROCAS DE OBRA: pos 73: mantida Casey at the Bat, com cena de táxi a caminho do estádio
# TROCAS DE OBRA: pos 75: mantida The Railway Children, mas o cenário passa do aeroporto para a estação de trem (vocabulário ajustado)
# (demais posições mantêm a obra do brief: 70 Busy Bee, 72 Peppa Pig, 74 Jingle Bells, 76 America the Beautiful, 77 Goldilocks)


def Q(q, pt, opts, a, line, why):
    return dict(q=q, pt=pt, opts=[list(o) for o in opts], a=a, line=line, why=why)


def H(e, x, y, en, pt, say, sayPt):
    return dict(e=e, x=x, y=y, en=en, pt=pt, say=say, sayPt=sayPt)


def G(q, pt, opts, a, why):
    return dict(q=q, pt=pt, opts=opts, a=a, why=why)


def T(opts, a, why, q='Qual frase está certa?'):
    return dict(q=q, opts=opts, a=a, why=why)


def EXP(ic, en, tag, pt, use, ex):
    return dict(ic=ic, en=en, tag=tag, pt=pt, use=use, ex=ex)


def VBI(v, ic, pt, i_s, he_s, ex_pt, form):
    return dict(v=v, ic=ic, pt=pt, f=[['eu', i_s], ['ele/ela', he_s]], ex=[i_s, ex_pt],
                note='**%s** = %s. Com he/she: **%s**.' % (v, pt, form))


def MSL(cat, *opts):
    return dict(cat=cat, opts=[list(o) for o in opts])


def MOLD(label, slots, end=('.', '.')):
    return dict(label=label, slots=slots, end=list(end))


def MIS(ic, name, desc, prompt, chips, model, check, kw, tips, ok, reply, ph='Escreva a sua resposta aqui…'):
    return dict(ic=ic, name=name, desc=desc, data=dict(prompt=prompt, ph=ph, chips=chips, model=model, check=check, kw=kw, tips=tips, ok=ok, reply=reply))


def CXI(text, pt, opts):
    return dict(text=text, pt=pt, opts=opts, a=0)


def RSD(rdg, pat, vplay, sbuild, build, order, balloons, dictate, soundlab, scene, dquiz, scenebuild, produce, review, wrap):
    return dict(rdg=rdg, pat=pat, vplay=vplay, sbuild=sbuild, build=build, order=order, balloons=balloons, dictate=dictate,
                soundlab=soundlab, scene=scene, dquiz=dquiz, scenebuild=scenebuild, produce=produce, review=review, wrap=wrap)


def PIC(say, ask, opts, a, why):
    return dict(fig='🎧', say=say, ask=ask, opts=[[o, ''] for o in opts], a=a, why=why, pic=1)


def TXT(say, opts, a, why, ask='Ouça e toque na palavra.'):
    return dict(fig='🎧', say=say, ask=ask, opts=opts, a=a, why=why)


def RND(say, opts, a, why):
    return dict(fig='🎧', say=say, ask='Qual palavra você ouviu?', opts=opts, a=a, why=why)


